SELECT t.THREAD_ID,t.PROCESSLIST_ID,t.PROCESSLIST_USER,t.PROCESSLIST_DB,t.PROCESSLIST_HOST,v.VARIABLE_NAME,v.VARIABLE_VALUE,a.ATTR_NAME,a.ATTR_VALUE FROM performance_schema.threads t JOIN performance_schema.variables_by_thread v ON t.THREAD_ID=v.THREAD_ID LEFT JOIN performance_schema.session_connect_attrs a ON t.PROCESSLIST_ID=a.PROCESSLIST_ID WHERE t.PROCESSLIST_USER='review_app' AND v.VARIABLE_NAME='time_zone' ORDER BY t.PROCESSLIST_ID,a.ORDINAL_POSITION;